// Generated by OrchestKit Claude Plugin
// Created: 2026-07-26

/**
 * Context-File Budget Guard — PreToolUse Write|Edit Hook
 *
 * MEMORY.md and CLAUDE.md are loaded into EVERY session's context. Both have
 * hard ceilings that fail silently when crossed: MEMORY.md stops loading past
 * the ~24 KB read limit (the whole index degrades, no error), and CLAUDE.md
 * burns its bytes as permanent per-session token overhead.
 *
 * The only existing control was post-hoc (CI perf test / dream-skill report),
 * which surfaces the overflow AFTER the write landed — measured 2026-07-26:
 * an index rebuild discovered its 17 KB target was structurally unreachable
 * only at the END of the task. This hook does the arithmetic BEFORE the write
 * lands: it projects the post-write byte size and, when the projection crosses
 * the budget, returns advisory context that the write-edit dispatcher merges
 * and the model reads on the same turn.
 *
 * ADVISORY, never ASK (2026-09-01). It asked in non-bypass modes until then,
 * and the day both MEMORY.md indexes sat over budget every handoff write in
 * every lane raised a permission dialog (since CC 2.1.211 a hook's ask wins
 * even under auto mode). ork's stance since the #3835 purge is that a plugin
 * hook never prompts; the opinion here is "trim the index", which the model
 * can act on itself (/ork:dream index-budget). A deny would repeat the #2947
 * display-lint mistake and teach users the escape hatch instead.
 *
 * Edit inputs carry old_string/new_string diffs, not the full body, so the
 * projection reads the current file and applies the replacement to compute
 * the real post-write size (a plain size delta would be wrong for
 * replace_all and for multi-occurrence strings).
 */

import type { HookInput, HookResult, HookContext } from '../../types.js';
import { outputSilentSuccess, logHook, outputPreToolAdvisory } from '../../lib/common.js';
import { readFileSync, existsSync } from 'node:fs';
import { basename } from 'node:path';
import { NOOP_CTX } from '../../lib/context.js';

const HOOK_NAME = 'context-file-budget-guard';

/**
 * Byte budgets per guarded basename. Sources:
 * - MEMORY.md: dream skill's index budget (17 KB target; the often-quoted
 *   ~24 KB hard read limit is unmeasured: two probes read past it, #3741).
 * - CLAUDE.md: token-overhead perf gate treats project instructions as a
 *   permanent per-session cost; 20 KB is the advisory line used here.
 * Override via ORK_CONTEXT_FILE_BUDGET_BYTES (applies to all guarded files).
 */
const DEFAULT_BUDGETS: Record<string, number> = {
  'MEMORY.md': 17 * 1024,
  'CLAUDE.md': 20 * 1024,
};

function budgetFor(fileName: string): number | null {
  const override = process.env.ORK_CONTEXT_FILE_BUDGET_BYTES;
  if (override) {
    const parsed = parseInt(override, 10);
    if (!Number.isNaN(parsed) && parsed > 0) return parsed;
  }
  return DEFAULT_BUDGETS[fileName] ?? null;
}

/**
 * Project the post-write byte size for this tool call.
 * Returns null when projection is impossible (treat as pass-through —
 * this guard must never block on its own failure).
 */
function projectSize(input: HookInput): number | null {
  const ti = input.tool_input as {
    file_path?: string;
    content?: string;
    old_string?: string;
    new_string?: string;
    replace_all?: boolean;
  };
  if (!ti?.file_path) return null;

  // Write: the new content IS the full body.
  if (input.tool_name === 'Write' && typeof ti.content === 'string') {
    return Buffer.byteLength(ti.content, 'utf8');
  }

  // Edit: read current body, apply the replacement, measure the result.
  if (input.tool_name === 'Edit' && typeof ti.old_string === 'string' && typeof ti.new_string === 'string') {
    if (!existsSync(ti.file_path)) return null; // Edit on a missing file fails upstream anyway
    let body: string;
    try {
      body = readFileSync(ti.file_path, 'utf8');
    } catch {
      return null; // unreadable (permissions/race) — fail open, Edit itself will surface it
    }
    if (!body.includes(ti.old_string)) return null; // Edit will error upstream; nothing to project
    const applied = ti.replace_all
      ? body.split(ti.old_string).join(ti.new_string)
      : body.replace(ti.old_string, ti.new_string);
    return Buffer.byteLength(applied, 'utf8');
  }

  return null;
}

export function contextFileBudgetGuard(input: HookInput, _ctx: HookContext = NOOP_CTX): HookResult {
  const ti = input.tool_input as { file_path?: string };
  const filePath = ti?.file_path;
  if (!filePath) return outputSilentSuccess();

  const fileName = basename(filePath);
  const budget = budgetFor(fileName);
  if (budget === null) return outputSilentSuccess(); // not a guarded file

  const projected = projectSize(input);
  if (projected === null || projected <= budget) return outputSilentSuccess();

  const currentSize = existsSync(filePath) ? Buffer.byteLength(readFileSync(filePath, 'utf8'), 'utf8') : 0;
  const overBy = projected - budget;
  // Advisory context is the only channel that reaches the model here: the
  // write-edit dispatcher merges additionalContext and drops systemMessage
  // (the #3801 class), and a permission ask is deliberately not an option.
  const advisory =
    `[${HOOK_NAME}] not asking, advising: this ${input.tool_name} puts ${fileName} at ` +
    `${(projected / 1024).toFixed(1)} KB, ${(overBy / 1024).toFixed(1)} KB over its ` +
    `${(budget / 1024).toFixed(0)} KB budget (currently ${(currentSize / 1024).toFixed(1)} KB). ` +
    `${fileName} loads into every session; past its read limit it degrades silently. ` +
    `Trim, or run /ork:dream (index-budget) before writing more. ` +
    `(Override budget: ORK_CONTEXT_FILE_BUDGET_BYTES=<bytes>)`;
  logHook(HOOK_NAME, `ADVISORY: ${fileName} projected ${projected}B > budget ${budget}B`);
  return outputPreToolAdvisory(advisory);
}
